-- A qualified type name whose schema does not exist reports the schema
-- (3F000) before the type (42704), at the type name, wherever a type is
-- named; dotted names past schema.type name another database or are improper.
SELECT '1'::nope.int4;
SELECT CAST(1 AS nope.t);
SELECT 1::nope.t[];
SELECT 1::"Nope".x;
SELECT NULL::nope.int4 IS NULL;
SELECT row(1)::nope.t;
SELECT '{}'::json::nope.t;
SELECT 1::pg_temp.foo;
SELECT 1::public.nope;
SELECT 1::public.nope[];
SELECT '1'::pg_catalog.nope;
SELECT 1::pg_catalog.integer;
SELECT 1::pg_catalog."char", 65::"char", (-1)::"char";
SELECT 200::"char";
SELECT 1::information_schema.foo;
SELECT '1'::a.b.int4;
SELECT '1'::a.b.c.int4;
SELECT '1'::postgres.nope.int4;
SELECT '1'::postgres.pg_catalog.int4;
SELECT JSON_VALUE('1', '$' RETURNING nope.t);
SELECT pg_input_is_valid('1', 'nope.int4');
-- Type input and lookup functions.
SELECT 'nope.int4'::regtype;
SELECT 'nope.t[]'::regtype;
SELECT 'pg_catalog.nope'::regtype;
SELECT 'a.b.int4'::regtype;
SELECT 'a.b.c.int4'::regtype;
SELECT 'postgres.pg_catalog.int4'::regtype;
SELECT 'postgres.nope.int4'::regtype;
SELECT to_regtype('nope.int4') IS NULL, to_regtype('pg_catalog.nope') IS NULL;
SELECT to_regtype('postgres.pg_catalog.int4');
SELECT to_regtype('a.b.int4');
SELECT to_regtype('a.b.c.int4');
SELECT to_regtypemod('nope.int4') IS NULL;
SELECT to_regtypemod('a.b.c.int4');
SELECT 'a.b.c'::regproc;
SELECT 'a.b.c.d'::regproc;
SELECT 'a.b.c.d(int)'::regprocedure;
SELECT 'a.b.c'::regclass;
SELECT 'a.b.c.d'::regclass;
-- Column, domain, composite and parameter types.
CREATE TABLE t452 (a nope.int4);
CREATE TABLE t452 (a nope.int4[]);
CREATE TABLE t452 (a pg_catalog.nope);
CREATE TABLE t452 OF nope.c;
CREATE TABLE t452 OF public.nope;
CREATE TABLE t452 (a int);
ALTER TABLE t452 ALTER COLUMN a TYPE nope.x;
ALTER TABLE t452 ADD COLUMN b nope.x;
CREATE DOMAIN d452 AS nope.int4;
CREATE TYPE c452 AS (x nope.int4);
CREATE TYPE c452 AS (x int);
ALTER TYPE c452 ADD ATTRIBUTE y nope.int4;
PREPARE p452(nope.int4) AS SELECT 1;
DO $$ DECLARE v nope.t; BEGIN END $$;
DO $$ DECLARE v nope.int4[]; BEGIN END $$;
DO $$ DECLARE v t452.a%TYPE; w nope.int4; BEGIN END $$;
-- Routine signatures: a parameter's missing type is named without quotes.
CREATE FUNCTION f452(nope.t) RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION f452(int, public.nope[]) RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION f452(OUT x nope.t) LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION f452() RETURNS TABLE (x nope.t) LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION f452(nope.t) RETURNS nope2.t LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION f452(int) RETURNS nope.t LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION f452() RETURNS SETOF public.nope LANGUAGE sql AS 'SELECT 1';
CREATE PROCEDURE p452(nope.t) LANGUAGE sql AS 'SELECT 1';
CREATE AGGREGATE a452(nope.t) (SFUNC = int4pl, STYPE = int);
CREATE AGGREGATE a452(public.nope) (SFUNC = int4pl, STYPE = int);
CREATE AGGREGATE a452(int) (SFUNC = int4pl, STYPE = nope.t);
DROP FUNCTION f452(nope.t);
DROP FUNCTION IF EXISTS f452(nope.t);
DROP AGGREGATE IF EXISTS a452(nope.t);
CREATE CAST (nope.t AS int) WITH INOUT;
CREATE OPERATOR === (LEFTARG = nope.t, RIGHTARG = int, FUNCTION = int4eq);
-- Commands that name an existing type.
DROP TYPE nope.t;
DROP TYPE IF EXISTS nope.t, public.nope, c452;
DROP DOMAIN nope.d;
DROP DOMAIN IF EXISTS nope.d, public.nope;
ALTER TYPE nope.c OWNER TO postgres;
ALTER DOMAIN nope.c OWNER TO postgres;
ALTER TYPE public.nope OWNER TO postgres;
ALTER DOMAIN nope.d SET DEFAULT 1;
ALTER TYPE nope.c ADD VALUE 'x';
ALTER TYPE nope.c RENAME TO u;
GRANT USAGE ON TYPE nope.c TO public;
GRANT USAGE ON DOMAIN public.nope TO public;
COMMENT ON TYPE nope.t IS 'x';
COMMENT ON TYPE public.nope IS 'x';
DROP TABLE t452;
